import{_ as a,I as t,g as o,j as s}from"./chunks/framework.CjoWWfVe.js";const h=JSON.parse('{"title":"PRO: Multi-Workspaces & Personal Finance","description":"Managing multiple business entities in a single application, global unified backups, and revolutionary automatic personal expenditure tracking.","frontmatter":{"title":"PRO: Multi-Workspaces & Personal Finance","description":"Managing multiple business entities in a single application, global unified backups, and revolutionary automatic personal expenditure tracking.","order":15},"headers":[],"relativePath":"docs/spaces/moy-kapital/pro-mode.md","filePath":"docs/spaces/moy-kapital/pro-mode.md"}'),i={name:"docs/spaces/moy-kapital/pro-mode.md"};function n(r,e,l,c,d,p){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="👑-pro-mode-an-ecosystem-for-scaling" tabindex="-1">👑 PRO Mode: An Ecosystem for Scaling <a class="header-anchor" href="#👑-pro-mode-an-ecosystem-for-scaling" aria-label="Permalink to &quot;👑 PRO Mode: An Ecosystem for Scaling&quot;">​</a></h1><p><strong>PRO Mode</strong> is the premium architecture of OmniCraft ERP, turning a local application from a single-workshop tracker into a comprehensive <strong>capital management ecosystem</strong>.</p><p>This mode introduces two major features:</p><ol><li><strong>Multi-Workspaces:</strong> Managing multiple independent business entities with completely isolated databases.</li><li><strong>Global &quot;My Capital&quot; Tab:</strong> Automatic tracking of personal finances via a mathematical delta, eliminating the need to log every coffee receipt.</li></ol><div class="info custom-block"><p class="custom-block-title">How to Activate PRO?</p><p>PRO mode is activated by a flag in your license key. As soon as a <code>Pro</code> license key is entered into the <strong>Settings</strong> tab, the program instantly unlocks the sliding side panel (Drawer) and the global consolidation tools.</p></div><hr><h2 id="🗂️-multi-workspaces" tabindex="-1">🗂️ Multi-Workspaces <a class="header-anchor" href="#🗂️-multi-workspaces" aria-label="Permalink to &quot;🗂️ Multi-Workspaces&quot;">​</a></h2><p>Many craftsmen eventually launch adjacent projects: their main leather workshop, selling digital PDF patterns/templates, hosting classes, or offering repair services. Mixing all of this into a single database is a poor idea: different currencies, varying markups, separate warehouses, and completely different economics.</p><p>PRO mode allows you to create <strong>an unlimited number of isolated workspaces</strong>. Each workspace is a complete, separate SQLite database file with its own directories, product recipes, stock, and transaction histories.</p><h3 id="🎛️-how-it-works-drawer-ui" tabindex="-1">🎛️ How It Works (Drawer UI) <a class="header-anchor" href="#🎛️-how-it-works-drawer-ui" aria-label="Permalink to &quot;🎛️ How It Works (Drawer UI)&quot;">​</a></h3><p>A <strong>&quot;Workspaces &amp; Modules&quot;</strong> button appears in the top-right corner of the window. Clicking it slides open the right side panel (Navigation Drawer), which becomes your primary dispatch console.</p><p>The top section of the panel displays a list of all your created workspaces:</p><ul><li>🟢 <strong>Green Icon:</strong> The current active workspace whose data is currently displayed on your screen.</li><li>⚪ <strong>Grey Icon:</strong> Your other registered databases. Click them to switch instantly.</li></ul><p>Upon switching, the program replaces the active database path on the fly. The entire interface (Workshop, Calculator, Cash Flow tabs, etc.) reloads immediately, pulling up the records, stock, and analytics of the selected business.</p><h3 id="➕-creating-a-new-workspace" tabindex="-1">➕ Creating a New Workspace <a class="header-anchor" href="#➕-creating-a-new-workspace" aria-label="Permalink to &quot;➕ Creating a New Workspace&quot;">​</a></h3><p>At the bottom of the list is an <strong>&quot;Add Workspace&quot;</strong> button. Clicking it opens a dialog where you enter a clear name (for example, <em>“Patterns &amp; Digital”</em> or <em>“Leather Repairs”</em>).</p><p>The program automatically:</p><ol><li>Generates a unique ID and creates a new physical database file in your secure system folder.</li><li>Initializes all necessary tables within it (Stock, Workbench, Cash Flow, Capital, etc.).</li><li>Registers the workspace in the global <code>workspaces.json</code> registry.</li></ol><div class="tip custom-block"><p class="custom-block-title">Data Isolation</p><p>Workspaces are completely independent. Each business has its own master labor rate, global markup, overhead cost categories, and raw material stock. You can manage one business in Dollars and another in Euros, simply by changing the accounting currency in the settings of that specific workspace.</p></div><hr><h2 id="💾-unified-global-backup" tabindex="-1">💾 Unified Global Backup <a class="header-anchor" href="#💾-unified-global-backup" aria-label="Permalink to &quot;💾 Unified Global Backup&quot;">​</a></h2><p>In PRO mode, the backup system scales up. Instead of exporting each database individually, the program packages <strong>absolutely everything</strong> into a single ZIP archive:</p><ul><li>🗃️ The workspaces registry (<code>workspaces.json</code>).</li><li>📦 The default database (<code>omnicraft_erp.db</code>).</li><li>📁 The entire <code>workspaces/</code> directory containing all your additional businesses.</li><li>💳 The global personal finance database (<code>personal_finance.db</code>).</li></ul><p>This means that to completely transfer your ecosystem to a new computer or to create a reliable backup copy, you only need to perform <strong>a single click</strong> in the <code>File ➔ Export Data</code> menu.</p><hr><h2 id="🏦-global-my-capital-tab-personal-finance" tabindex="-1">🏦 Global &quot;My Capital&quot; Tab (Personal Finance) <a class="header-anchor" href="#🏦-global-my-capital-tab-personal-finance" aria-label="Permalink to &quot;🏦 Global &quot;My Capital&quot; Tab (Personal Finance)&quot;">​</a></h2><p>This is, perhaps, the most innovative feature of OmniCraft ERP. It solves the biggest headache of any entrepreneur: <strong>how to track personal money without turning into an accountant who logs every loaf of bread in a spreadsheet?</strong></p><p>In PRO mode, a prominent <strong>&quot;My Capital&quot;</strong> button appears in the side panel. Clicking it hides the standard business tabs and opens a global dashboard divided into four sub-sections.</p><h3 id="_1-💳-my-accounts-investments" tabindex="-1">1. 💳 My Accounts &amp; Investments <a class="header-anchor" href="#_1-💳-my-accounts-investments" aria-label="Permalink to &quot;1. 💳 My Accounts &amp; Investments&quot;">​</a></h3><p>A unified hub for your liquidity outside of business operations. Here, you set up cards for:</p><ul><li>Bank cards (debit, credit).</li><li>Cash holdings.</li><li>Brokerage accounts (stocks, bonds).</li><li>Foreign currency wallets and crypto accounts.</li><li>Deposits and savings accounts.</li></ul><p><strong>How to keep records:</strong> You do not need to record every transaction on your cards. Simply visit this section periodically (e.g., once a week or on payday), click the pencil icon on the account card, and <strong>input its actual current balance</strong>. The program will automatically record the delta.</p><h3 id="_2-🏠-my-assets" tabindex="-1">2. 🏠 My Assets <a class="header-anchor" href="#_2-🏠-my-assets" aria-label="Permalink to &quot;2. 🏠 My Assets&quot;">​</a></h3><p>Tracking of major and minor personal property not associated with your business:</p><ul><li>Real estate (house, land).</li><li>Vehicles.</li><li>Valuable personal belongings (electronics, jewelry).</li></ul><p>You enter the purchase cost and current estimated value. These figures shape your personal Net Worth.</p><h3 id="_3-📝-significant-transactions" tabindex="-1">3. 📝 Significant Transactions <a class="header-anchor" href="#_3-📝-significant-transactions" aria-label="Permalink to &quot;3. 📝 Significant Transactions&quot;">​</a></h3><p>A ledger for recording only <strong>significant</strong> external cash flows that cannot be ignored:</p><ul><li><em>External Income:</em> Salary from employment, one-off freelance work, dividends, donations.</li><li><em>Targeted Expenses:</em> Mortgage payments, vacation bookings, major medical expenses.</li></ul><h3 id="_4-📊-dashboard-the-magic-of-consolidation" tabindex="-1">4. 📊 Dashboard (The Magic of Consolidation) <a class="header-anchor" href="#_4-📊-dashboard-the-magic-of-consolidation" aria-label="Permalink to &quot;4. 📊 Dashboard (The Magic of Consolidation)&quot;">​</a></h3><p>The heart of the &quot;My Capital&quot; tab. Here, the program merges the data from all your business workspaces and personal accounts to calculate four global indicators:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Metric</th><th style="text-align:left;">What It Means</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>💎 Net Worth (Total Capital)</strong></td><td style="text-align:left;">The sum of all assets from all businesses + Personal Accounts + Personal Assets. Your cumulative wealth at the current second.</td></tr><tr><td style="text-align:left;"><strong>💰 Earned in Businesses</strong></td><td style="text-align:left;">Consolidated net profit (P&amp;L) from all active workspaces over all time.</td></tr><tr><td style="text-align:left;"><strong>📈 External Income / Accumulated</strong></td><td style="text-align:left;">The sum of all major personal income entries not related to your businesses.</td></tr><tr><td style="text-align:left;"><strong>🔍 Free Expenses on Life</strong></td><td style="text-align:left;">That &quot;magical&quot; figure (see below).</td></tr></tbody></table><h4 id="🧠-the-magical-formula-of-free-expenses" tabindex="-1">🧠 The Magical Formula of Free Expenses <a class="header-anchor" href="#🧠-the-magical-formula-of-free-expenses" aria-label="Permalink to &quot;🧠 The Magical Formula of Free Expenses&quot;">​</a></h4><p>How does the program know how much you spent on life (food, fuel, coffee, clothing) if you didn&#39;t log those receipts? It calculates them <strong>from the reverse</strong>, using your capital delta:</p><p>$$\\text{Free Expenses} = \\text{Business Profit} + \\text{External Income} - \\text{Significant Personal Expenses} - \\text{Actual Capital Growth}$$</p><p><strong>How it works in practice:</strong></p><ol><li>The program sees that your businesses generated <strong>$10,000</strong> in net profit.</li><li>You received a salary at your day job of <strong>$5,000</strong> (recorded as External Income).</li><li>You paid your mortgage of <strong>$3,000</strong> (recorded as a Significant Expense).</li><li><em>Theoretically</em>, your money should have increased by <strong>$12,000</strong> (<code>$10,000</code> + <code>$5,000</code> - <code>$3,000</code>).</li><li>But the program checks your real bank accounts and sees that your total balance only grew by <strong>$4,000</strong>.</li><li><strong>Conclusion:</strong> You spent <strong>$8,000</strong> (<code>$12,000</code> - <code>$4,000</code>) on daily life. The program will display this exact figure in the &quot;Free Expenses on Life&quot; block.</li></ol><div class="tip custom-block"><p class="custom-block-title">The &quot;No-Friction Accounting&quot; Philosophy</p><p>This approach completely eliminates personal budget micromanagement. You do not need to scan supermarket receipts. The program acts as an honest mirror: it shows the volume of cash that &quot;dissolves&quot; into daily life, allowing you to evaluate your true standard of living and adjust financial goals based on solid mathematical facts.</p></div><hr><h2 id="🧩-global-theme-modules-add-ons" tabindex="-1">🧩 Global Theme Modules (Add-ons) <a class="header-anchor" href="#🧩-global-theme-modules-add-ons" aria-label="Permalink to &quot;🧩 Global Theme Modules (Add-ons)&quot;">​</a></h2><p>In the future, <strong>Global Modules</strong>—specialized niche tools that can be purchased separately—will appear in the lower section of the sliding panel (Drawer).</p><p>They are called &quot;global&quot; because <strong>they are not tied to a specific database</strong>. For example, if you purchase the &quot;Patterns Module&quot;, it will be accessible from any active workspace, allowing you to maintain a unified catalog of patterns/blueprints for all your separate brands.</p><p>Module and status management is also centralized in the Drawer and tied to your unified license key, which &quot;evolves&quot; as you expand your ecosystem.</p>',53)])])}const g=a(i,[["render",n]]);export{h as __pageData,g as default};
